#include <iostream>
#include <set>

int main() {
    int n = 0;
    if (!(std::cin >> n)) return 1;
    if (n < 1 || n > 1000) return 1;
    std::set<int> unique_values;
    for (int i = 0; i < n; i++) {
        int value = 0;
        if (!(std::cin >> value)) return 1;
        if (value < -10000 || value > 10000) return 1;
        unique_values.insert(value);
    }
    std::cout << unique_values.size() << std::endl;
    return 0;
}
